import json
import datetime
import re

def cliniko(tool, args):
    return api.connectors.invoke(server="cliniko-scheduling", tool=tool, args=args) or {}

def read_json(path):
    try:
        raw = api.files.read(file=path, scope="org")
    except Exception:
        return None
    try:
        return json.loads(raw)
    except Exception:
        return None

def write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True), scope="org")

def delete_file(path):
    try:
        api.files.delete(file=path, scope="org")
    except Exception:
        pass

def link_id(obj, key):
    link = ((obj.get(key) or {}).get("links") or {}).get("self") or ""
    return link.rstrip("/").split("/")[-1] if link else ""

slug = params["slug"]
conversation_id = params["conversation_id"]
appointment_id = params["appointment_id"]
proposed_times_raw = params["proposed_times_raw"] or []
proposed_times_display = params["proposed_times_display"] or []
patient_name = params["patient_name"]
from_email = params["from_email"]
replied_at = params["replied_at"]
commitment_id = params["commitment_id"]
file_name = params["file_name"]
state_path = "PracticeManager/State/" + file_name

result = "no_reply_yet"

if not conversation_id or not proposed_times_raw:
    result = "incomplete_record"
else:
    # Expire anything still unanswered after a week — don't poll forever.
    stale = False
    try:
        replied_dt = datetime.datetime.fromisoformat(replied_at.replace("Z", "+00:00"))
        stale = (datetime.datetime.now(datetime.timezone.utc) - replied_dt) > datetime.timedelta(days=7)
    except Exception:
        stale = False

    raw_messages = api.connectors.invoke(server="m365-mail-read", tool="list_emails", args={"folder": "inbox", "limit": 25})
    messages = raw_messages if isinstance(raw_messages, list) else ((raw_messages or {}).get("value") or [])

    reply = None
    for m in messages:
        if m.get("conversationId") != conversation_id:
            continue
        received = m.get("receivedDateTime") or ""
        if received and replied_at and received > replied_at:
            reply = m
            break

    if reply is None:
        result = "stale" if stale else "no_reply_yet"
    else:
        # bodyPreview is a short, auto-truncated preview -- too thin to safely
        # hand to the matching prompt below. Fetch the full message instead;
        # fall back to the preview only if that call fails for some reason.
        reply_text = ""
        try:
            full = api.connectors.invoke(server="m365-mail-read", tool="get_email", args={"id": reply.get("id") or ""}) or {}
            content = ((full.get("body") or {}).get("content")) or ""
            if content:
                # Body may be HTML. Turn line-break-producing tags into real
                # newlines FIRST -- otherwise stripping every tag to a space
                # collapses the whole message onto one line, and the quote-
                # header search just below (which needs "From:" at the start
                # of an actual line) would never match anything.
                plain = re.sub(r"(?i)<br\s*/?>|</p>|</div>|</tr>", "\n", content)
                plain = re.sub(r"<[^>]+>", " ", plain)
                plain = re.sub(r"[ \t]+", " ", plain)
                # Outlook inserts a quote header ("From: ... Sent: ... To:
                # ... Subject: ...") above the quoted original message on
                # every reply -- cut the text there so matching never sees
                # the offer's own times quoted back at it.
                quote_start = re.search(r"(?im)^\s*(From:|Sent:|On .{0,80} wrote:)", plain)
                if quote_start:
                    plain = plain[: quote_start.start()]
                reply_text = re.sub(r"\s+", " ", plain).strip()
        except Exception:
            reply_text = ""
        if not reply_text:
            reply_text = reply.get("bodyPreview") or ""

        practice = read_json("PracticeManager/Practices/" + slug + ".json") or {}
        tz_name = practice.get("timezone") or "UTC"

        def format_local(iso_str):
            try:
                from zoneinfo import ZoneInfo
                local = datetime.datetime.fromisoformat(iso_str.replace("Z", "+00:00")).astimezone(ZoneInfo(tz_name))
            except Exception:
                return iso_str
            return local.strftime("%a %d %b, %I:%M %p").replace(" 0", " ")

        def to_utc_iso(local_str):
            # The model returns a naive "YYYY-MM-DDTHH:MM" in the practice's
            # own local time (matching how times were offered to the patient)
            # -- convert to a real UTC instant before touching Cliniko with it.
            try:
                from zoneinfo import ZoneInfo
                naive = datetime.datetime.fromisoformat(local_str)
                aware = naive if naive.tzinfo is not None else naive.replace(tzinfo=ZoneInfo(tz_name))
                return aware.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
            except Exception:
                return ""

        chosen_iso = ""
        chosen_display = ""
        ai_raw = ""
        ai_error = ""
        custom_rejected_reason = ""
        try:
            options_text = "\n".join(
                str(i + 1) + ". " + proposed_times_display[i] + " (" + proposed_times_raw[i] + ")"
                for i in range(len(proposed_times_raw))
            )
            now_local_str = format_local(datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"))
            prompt = (
                "A patient was offered these appointment time options (practice timezone " + tz_name
                + ", current local time " + now_local_str + "):\n" + options_text + "\n\n"
                'They replied: "' + reply_text + '"\n\n'
                "Which option number did they choose? If instead they proposed a different specific "
                "day and time of their own (not one of the options above), extract it as a local "
                "date-time in the practice's own timezone, formatted exactly as YYYY-MM-DDTHH:MM (no "
                "timezone suffix), resolving relative terms like 'next Tuesday' against the current "
                "local time given above. Reply with ONLY JSON, no markdown or code fences, just the "
                'object: {"option": <1-based number or null>, "custom_datetime": <"YYYY-MM-DDTHH:MM" or null>}'
            )
            ai_raw = api.ai.generate(prompt=prompt) or ""
            # Models sometimes wrap JSON in ```json ... ``` fences despite being told not
            # to -- strip those before parsing instead of letting json.loads blow up and
            # silently fall through to flagged_for_human with no trace of why.
            cleaned = ai_raw.strip()
            if cleaned.startswith("```"):
                cleaned = re.sub(r"^```[a-zA-Z]*\n?", "", cleaned)
                cleaned = re.sub(r"```\s*$", "", cleaned)
            parsed = json.loads(cleaned.strip()) or {}
            option = parsed.get("option")
            if isinstance(option, int) and 1 <= option <= len(proposed_times_raw):
                chosen_iso = proposed_times_raw[option - 1]
                chosen_display = proposed_times_display[option - 1]
            else:
                custom_local = parsed.get("custom_datetime")
                if isinstance(custom_local, str) and custom_local.strip():
                    candidate_iso = to_utc_iso(custom_local.strip())
                    if not candidate_iso:
                        custom_rejected_reason = "Couldn't parse the date/time they proposed (\"" + custom_local + "\")."
                    else:
                        candidate_dt = datetime.datetime.fromisoformat(candidate_iso.replace("Z", "+00:00"))
                        if candidate_dt <= datetime.datetime.now(datetime.timezone.utc):
                            custom_rejected_reason = (
                                "They proposed " + format_local(candidate_iso) + ", which is already in the past."
                            )
                        else:
                            appt = cliniko("get_individual_appointment", {"id": appointment_id}) or {}
                            practitioner_id = link_id(appt, "practitioner")
                            business_id = link_id(appt, "business")
                            appt_starts_at = appt.get("starts_at") or ""
                            appt_ends_at = appt.get("ends_at") or ""
                            duration = datetime.timedelta(minutes=30)
                            try:
                                if appt_starts_at and appt_ends_at:
                                    duration = (
                                        datetime.datetime.fromisoformat(appt_ends_at.replace("Z", "+00:00"))
                                        - datetime.datetime.fromisoformat(appt_starts_at.replace("Z", "+00:00"))
                                    )
                            except Exception:
                                pass
                            candidate_end_dt = candidate_dt + duration

                            from zoneinfo import ZoneInfo
                            try:
                                local_dt = candidate_dt.astimezone(ZoneInfo(tz_name))
                            except Exception:
                                local_dt = candidate_dt

                            # Working-hours check -- same Daily Availability cross-check used
                            # in the Draft automation (#1174); fails open if no data comes back,
                            # same as there.
                            within_hours = True
                            if practitioner_id:
                                try:
                                    windows_by_day = {}
                                    avail_result = cliniko(
                                        "list_daily_availabilities",
                                        {"business_id": business_id, "practitioner_id": practitioner_id, "per_page": 100},
                                    )
                                    for rec in (avail_result or {}).get("daily_availabilities") or []:
                                        day = rec.get("day_of_week")
                                        if day is None:
                                            continue
                                        for block in rec.get("availabilities") or []:
                                            start, end = block.get("starts_at"), block.get("ends_at")
                                            if start and end:
                                                windows_by_day.setdefault(day, []).append((start, end))
                                    if windows_by_day:
                                        day = (local_dt.weekday() + 1) % 7
                                        hhmm = local_dt.strftime("%H:%M")
                                        within_hours = any(
                                            start <= hhmm < end for start, end in windows_by_day.get(day, [])
                                        )
                                except Exception:
                                    within_hours = True

                            if not within_hours:
                                custom_rejected_reason = (
                                    "They proposed " + format_local(candidate_iso)
                                    + ", which is outside the practitioner's configured working hours."
                                )
                            else:
                                # Conflict check -- make sure nothing else already occupies that slot
                                # before booking it (never silently double-book over an existing patient).
                                has_conflict = False
                                try:
                                    local_day_start = local_dt.replace(hour=0, minute=0, second=0, microsecond=0)
                                    local_day_end = local_day_start + datetime.timedelta(days=1)
                                    day_start_utc = local_day_start.astimezone(datetime.timezone.utc)
                                    day_end_utc = local_day_end.astimezone(datetime.timezone.utc)
                                    existing = cliniko(
                                        "list_individual_appointments",
                                        {
                                            "practitioner_id": practitioner_id,
                                            "business_id": business_id,
                                            "q": [
                                                "starts_at:>=" + day_start_utc.strftime("%Y-%m-%dT%H:%M:%SZ"),
                                                "starts_at:<" + day_end_utc.strftime("%Y-%m-%dT%H:%M:%SZ"),
                                            ],
                                            "per_page": 100,
                                        },
                                    ) or {}
                                    for other in existing.get("individual_appointments") or []:
                                        if (other.get("id") or "") == appointment_id:
                                            continue
                                        if other.get("cancelled_at"):
                                            continue
                                        o_start = other.get("starts_at") or ""
                                        o_end = other.get("ends_at") or o_start
                                        try:
                                            o_start_dt = datetime.datetime.fromisoformat(o_start.replace("Z", "+00:00"))
                                            o_end_dt = datetime.datetime.fromisoformat(o_end.replace("Z", "+00:00"))
                                        except Exception:
                                            continue
                                        if candidate_dt < o_end_dt and o_start_dt < candidate_end_dt:
                                            has_conflict = True
                                            break
                                except Exception:
                                    has_conflict = False

                                if has_conflict:
                                    custom_rejected_reason = (
                                        "They proposed " + format_local(candidate_iso) + ", but that slot is already booked."
                                    )
                                else:
                                    chosen_iso = candidate_iso
                                    chosen_display = format_local(candidate_iso)
        except Exception as exc:
            chosen_iso = ""
            ai_error = str(exc)

        commitments_path = "PracticeManager/Commitments/" + slug + ".json"

        if not chosen_iso:
            # Ambiguous reply — never guess which time to book. Flag for a
            # human instead of silently doing nothing or booking the wrong slot.
            PRACTITIONER_EMAIL = "sean.baker@mysmb.com"
            assignee_ids: list[str] = []
            try:
                users = api.users.list()
                for user in users or []:
                    if (user.get("email") or "").strip().lower() == PRACTITIONER_EMAIL:
                        user_id = user.get("id")
                        if user_id:
                            assignee_ids = [str(user_id)]
                        break
            except Exception:
                assignee_ids = []

            item = api.workq.create(
                title="Needs a human: unclear reschedule reply from " + (patient_name or from_email),
                scope="org",
                description=(
                    "**Patient:** " + (patient_name or from_email) + "\n"
                    + "**Matched email:** \"" + (reply.get("subject") or "(no subject)") + "\", received "
                    + (reply.get("receivedDateTime") or "unknown time")
                    + " — check this is actually their reply before anything else, not a different message "
                    + "in the same thread.\n"
                    + "**Their reply:** " + reply_text + "\n"
                    + "**Options offered:** " + ", ".join(proposed_times_display) + "\n"
                    + ("**Requested time not booked:** " + custom_rejected_reason + "\n" if custom_rejected_reason else "")
                    + ("**AI raw response:** " + ai_raw + "\n" if ai_raw else "")
                    + ("**AI parse error:** " + ai_error + "\n" if ai_error else "")
                    + "\n"
                    + "Couldn't tell which time they picked — please book it manually in Cliniko and reply "
                    + "to the patient yourself."
                ),
                priority="high",
                labels=["cliniko-automations", "reschedule-desk", "needs-human"],
                assignee_ids=assignee_ids or None,
            )
            delete_file(state_path)
            try:
                commitments = read_json(commitments_path) or []
                for c in commitments:
                    if c.get("id") == commitment_id:
                        c["status"] = "needs_human"
                write_json(commitments_path, commitments)
            except Exception:
                pass
            result = "flagged_for_human"
        else:
            update_error = ""
            try:
                # Cliniko doesn't shift ends_at when starts_at changes -- patching
                # starts_at alone leaves the old end time in place and gets a 422
                # ("end time must be greater than start time") on any move later
                # than the original slot. Send both, keeping the original length.
                current = cliniko("get_individual_appointment", {"id": appointment_id}) or {}
                length = datetime.timedelta(minutes=30)
                try:
                    cur_start = current.get("starts_at") or ""
                    cur_end = current.get("ends_at") or ""
                    if cur_start and cur_end:
                        length = (
                            datetime.datetime.fromisoformat(cur_end.replace("Z", "+00:00"))
                            - datetime.datetime.fromisoformat(cur_start.replace("Z", "+00:00"))
                        )
                except Exception:
                    pass
                new_start = datetime.datetime.fromisoformat(chosen_iso.replace("Z", "+00:00"))
                new_end_iso = (new_start + length).astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
                cliniko(
                    "update_individual_appointment",
                    {"id": appointment_id, "patch": {"starts_at": chosen_iso, "ends_at": new_end_iso}},
                )
                updated = True
            except Exception as exc:
                updated = False
                update_error = str(exc)

            if updated:
                # Leave the old time for "Find freed slots to fill" -- a move frees it,
                # but Cliniko doesn't mark the booking cancelled, so the gap filler's
                # own Cliniko check can't see it. Best-effort; never blocks the reply.
                try:
                    if current.get("starts_at"):
                        freed_path = "PracticeManager/State/" + slug + "-freed-slots.json"
                        freed = read_json(freed_path)
                        freed = freed if isinstance(freed, list) else []
                        freed.append({
                            "appointment_id": str(appointment_id),
                            "patient_id": link_id(current, "patient"),
                            "starts_at": current.get("starts_at") or "",
                            "ends_at": current.get("ends_at") or "",
                            "practitioner_id": link_id(current, "practitioner"),
                            "business_id": link_id(current, "business"),
                            "appointment_type_id": link_id(current, "appointment_type"),
                            "freed_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
                        })
                        write_json(freed_path, freed[-200:])
                except Exception:
                    pass
                confirm_text = (
                    "Hi " + (patient_name or "there") + ",<br><br>"
                    + "You're confirmed for your rescheduled appointment"
                    + (" on " + chosen_display if chosen_display else "")
                    + ". See you then!<br><br>Best regards"
                )
                try:
                    api.connectors.invoke(
                        server="m365-mail-send", tool="reply_to_email",
                        args={"id": reply.get("id") or "", "comment": confirm_text},
                    )
                except Exception:
                    pass
                delete_file(state_path)
                try:
                    commitments = read_json(commitments_path) or []
                    for c in commitments:
                        if c.get("id") == commitment_id:
                            c["status"] = "resolved"
                            c["resolved_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
                    write_json(commitments_path, commitments)
                except Exception:
                    pass
                result = "applied"
            else:
                # Their reply was matched fine -- Cliniko itself rejected the update.
                # Surface the real error instead of silently retrying forever with no
                # trace of why (same gap as the AI-matching diagnostics added earlier).
                PRACTITIONER_EMAIL = "sean.baker@mysmb.com"
                assignee_ids: list[str] = []
                try:
                    users = api.users.list()
                    for user in users or []:
                        if (user.get("email") or "").strip().lower() == PRACTITIONER_EMAIL:
                            user_id = user.get("id")
                            if user_id:
                                assignee_ids = [str(user_id)]
                            break
                except Exception:
                    assignee_ids = []

                item = api.workq.create(
                    title="Needs a human: couldn't move booking for " + (patient_name or from_email),
                    scope="org",
                    description=(
                        "**Patient:** " + (patient_name or from_email) + "\n"
                        + "**Requested new time:** " + (chosen_display or chosen_iso) + "\n"
                        + "**Cliniko error:** " + (update_error or "unknown error") + "\n\n"
                        + "Their reply was matched correctly, but Cliniko rejected the booking update -- "
                        + "please move the appointment manually in Cliniko and reply to the patient yourself."
                    ),
                    priority="high",
                    labels=["cliniko-automations", "reschedule-desk", "needs-human"],
                    assignee_ids=assignee_ids or None,
                )
                delete_file(state_path)
                try:
                    commitments = read_json(commitments_path) or []
                    for c in commitments:
                        if c.get("id") == commitment_id:
                            c["status"] = "needs_human"
                    write_json(commitments_path, commitments)
                except Exception:
                    pass
                result = "update_failed"
